request.schema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "docs",
  "description": "Documentation changes under docs/ (API notes, ADRs, scenario write-ups) as whole new file contents.",
  "type": "object",
  "additionalProperties": false,
  "required": ["summary", "files"],
  "properties": {
    "summary": { "type": "string", "minLength": 1 },
    "files": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "additionalProperties": false, "required": ["path", "newContent"],
        "properties": {
          "path": { "type": "string", "pattern": "^docs/" },
          "newContent": { "type": "string", "minLength": 1 }
        }
      }
    }
  }
}
